package org.brightstats.stats;
import java.util.*;
import java.util.function.IntConsumer;

/** Hierarchical raw/centered/standardized polynomial path equations of fixed observed variables. */
public final class ObservedPolynomial {
    private ObservedPolynomial(){}
    public record Model(List<String> names,int[] columns,List<PlsSem.Edge> paths,List<NonlinearPls.Extension> extensions,int source,int target,int[] controls){
        public Model{names=List.copyOf(names);columns=columns.clone();paths=List.copyOf(paths);extensions=List.copyOf(extensions);controls=controls.clone();int k=names.size();if(k<2||k>64||columns.length!=k||Arrays.stream(columns).anyMatch(c->c<0)||Arrays.stream(columns).distinct().count()!=k||names.stream().anyMatch(String::isBlank)||new HashSet<>(names).size()!=k||source<0||source>=k||target<0||target>=k||source==target||Arrays.stream(controls).anyMatch(c->c<0||c>=k||c==source||c==target)||Arrays.stream(controls).distinct().count()!=controls.length)throw new IllegalArgumentException("Invalid observed-polynomial variable bindings, focus or controls.");Set<Integer> controlSet=new HashSet<>();for(int control:controls)controlSet.add(control);for(var path:paths)if(controlSet.contains(path.target()))throw new IllegalArgumentException("A control cannot be an endogenous polynomial outcome.");for(var term:extensions)if(controlSet.contains(term.target()))throw new IllegalArgumentException("A control cannot be a polynomial outcome.");}
        @Override public int[] columns(){return columns.clone();}@Override public int[] controls(){return controls.clone();}
    }
    public record EquationInference(int target,RobustRegression.Fit regression){}
    public record Fit(Model model,PathProcess.Options options,NonlinearPls.Specification requested,List<PathProcess.Probe> rawProbes,double[] means,double[] centers,double[] scales,NonlinearPls.ScoreFit polynomial,List<EquationInference> equations,List<NonlinearPls.Effect> rawEffects,List<NonlinearPls.CurvePoint> rawCurves,List<String> warnings){
        public Fit{rawProbes=List.copyOf(rawProbes);means=means.clone();centers=centers.clone();scales=scales.clone();equations=List.copyOf(equations);rawEffects=List.copyOf(rawEffects);rawCurves=List.copyOf(rawCurves);warnings=List.copyOf(warnings);}@Override public double[] means(){return means.clone();}@Override public double[] centers(){return centers.clone();}@Override public double[] scales(){return scales.clone();}
    }
    public record Resampled(Fit point,Bootstrap.Result inference){}
    public static Fit fit(double[][] data,Model model,PathProcess.Options options,NonlinearPls.Specification requested){return compute(data,model,options,requested,true);}
    private static Fit compute(double[][] data,Model model,PathProcess.Options options,NonlinearPls.Specification requested,boolean details){
        int width=Matrices.width(data,3),n=data.length,k=model.names().size();if((long)n*k>5000000L||Arrays.stream(model.columns()).anyMatch(c->c>=width))throw new IllegalArgumentException("Polynomial selection exceeds the data or five million cells.");if(!requested.extensions().equals(model.extensions())){var gson=new com.google.gson.Gson();if(!gson.toJson(requested.extensions()).equals(gson.toJson(model.extensions())))throw new IllegalArgumentException("Polynomial requests differ from model extensions.");}
        double[][] values=new double[n][k];double[] means=new double[k],centers=new double[k],scales=new double[k];int[] selected=model.columns();for(int col=0;col<k;col++){Matrices.interrupted();for(int row=0;row<n;row++)means[col]+=(data[row][selected[col]]-means[col])/(row+1);centers[col]=options.metric()==PathProcess.Metric.UNSTANDARDIZED?0:means[col];double variance=0;for(var row:data)variance+=Math.pow(row[selected[col]]-means[col],2)/n;scales[col]=options.metric()==PathProcess.Metric.STANDARDIZED?Math.sqrt(variance):1;if(!Double.isFinite(means[col])||!(scales[col]>0)||!Double.isFinite(scales[col]))throw new IllegalArgumentException("A selected polynomial variable is nonfinite or unscalable: "+model.names().get(col));for(int row=0;row<n;row++)values[row][col]=(data[row][selected[col]]-centers[col])/scales[col];}
        List<PlsSem.Edge> paths=new ArrayList<>(model.paths());Set<Integer> targets=new TreeSet<>();for(var path:paths)targets.add(path.target());for(var term:model.extensions())targets.add(term.target());if(options.considerControls())for(int target:targets)for(int control:model.controls()){var edge=new PlsSem.Edge(control,target);if(!paths.contains(edge))paths.add(edge);}
        List<PathProcess.Probe> raw=new ArrayList<>(),transformed=new ArrayList<>();List<PathProcess.Probe> supplied=requested.probes().isEmpty()?List.of(new PathProcess.Probe("At observed means",Map.of())):requested.probes();for(var probe:supplied){if(probe.values().keySet().stream().anyMatch(col->col>=k))throw new IllegalArgumentException("Polynomial probe variable is outside the model.");Map<Integer,Double> rawValues=new LinkedHashMap<>(),scaled=new LinkedHashMap<>();for(int col=0;col<k;col++){double value=probe.values().getOrDefault(col,means[col]);rawValues.put(col,value);scaled.put(col,(value-centers[col])/scales[col]);}raw.add(new PathProcess.Probe(probe.name(),rawValues));transformed.add(new PathProcess.Probe(probe.name(),scaled));}
        NonlinearPls.Grid grid=null;if(requested.grid()!=null){var g=requested.grid();if(g.source()>=k||g.target()>=k)throw new IllegalArgumentException("Polynomial grid variable is outside the model.");grid=new NonlinearPls.Grid(g.source(),g.target(),(g.lower()-centers[g.source()])/scales[g.source()],(g.upper()-centers[g.source()])/scales[g.source()],g.points());}
        var polynomial=NonlinearPls.fitScores(values,model.names(),paths,new NonlinearPls.Specification(model.extensions(),transformed,grid),options.metric()!=PathProcess.Metric.UNSTANDARDIZED,details);List<EquationInference> equations=new ArrayList<>();if(details)for(var equation:polynomial.equations()){int count=equation.regressors().size();double[][] x=new double[n][count];double[] y=new double[n];for(int row=0;row<n;row++){y[row]=values[row][equation.target()];for(int col=0;col<count;col++){double product=1;for(int factor:equation.regressors().get(col).factors())product*=values[row][factor];x[row][col]=product;}}equations.add(new EquationInference(equation.target(),RobustRegression.fit(x,y,options.covariance(),options.confidence())));}
        List<NonlinearPls.Effect> effects=new ArrayList<>();for(var effect:polynomial.effects())effects.add(new NonlinearPls.Effect(effect.probe(),effect.family(),effect.source(),effect.target(),effect.route(),effect.value()*scales[effect.target()]/scales[effect.source()]));List<NonlinearPls.CurvePoint> curves=new ArrayList<>();for(var point:polynomial.curves())curves.add(new NonlinearPls.CurvePoint(point.probe(),point.source(),point.target(),centers[point.source()]+scales[point.source()]*point.x(),centers[point.target()]+scales[point.target()]*point.value()));
        List<String> warnings=new ArrayList<>();for(String warning:polynomial.warnings())if(!warning.contains("Generated")&&!warning.contains("generated-score")&&!warning.contains("composite-score"))warnings.add(warning.replace("observed first-stage score range","selected observed-variable range"));warnings.add("Fixed observed variables, including fixed MEAN/SUM composites when supplied, use ordinary hierarchical polynomial equations. These are not estimated latent factors or a nonlinear latent likelihood.");warnings.add("Model coefficients use "+options.metric()+" units; standardization uses population SD (divisor N), matching the observed PROCESS contract. Raw-unit derivatives and conditional fitted outcomes are reported separately.");warnings.add("Local total derivatives multiply equation Jacobians at the same specified probe vector. They are conditional associations, not population-average or causal effects. Indirect-effect uncertainty requires a paired full-equation bootstrap.");warnings.add("Curve values are conditional means of the selected response equation with other parent values held at the probe, not a recursive intervention simulation.");if(options.metric()!=PathProcess.Metric.UNSTANDARDIZED)warnings.add("Centered linear-only intercepts are definitionally zero; ratio tests for those identities are suppressed.");return new Fit(model,options,requested,raw,means,centers,scales,polynomial,equations,effects,curves,warnings);
    }
    private static List<Bootstrap.Parameter> parameters(Fit fit){List<Bootstrap.Parameter> result=new ArrayList<>(NonlinearPls.scoreParameters(fit.polynomial(),true));for(int i=0;i<fit.rawEffects().size();i++){var effect=fit.rawEffects().get(i);result.add(new Bootstrap.Parameter("Raw-unit "+effect.family(),effect.source(),effect.target(),i,effect.probe()+" "+effect.route()));}for(int i=0;i<fit.rawCurves().size();i++){var curve=fit.rawCurves().get(i);result.add(new Bootstrap.Parameter("Raw-unit conditional fitted outcome",curve.source(),curve.target(),i,curve.probe()+" x="+curve.x()));}return result;}
    private static double[] vector(Fit fit){double[] first=NonlinearPls.scoreValues(fit.polynomial(),true),result=Arrays.copyOf(first,first.length+fit.rawEffects().size()+fit.rawCurves().size());int index=first.length;for(var effect:fit.rawEffects())result[index++]=effect.value();for(var curve:fit.rawCurves())result[index++]=curve.value();return result;}
    public static Resampled bootstrap(double[][] data,Model model,PathProcess.Options options,NonlinearPls.Specification requested,Bootstrap.Options resampling,IntConsumer progress){var point=fit(data,model,options,requested);var frozen=new NonlinearPls.Specification(requested.extensions(),point.rawProbes(),requested.grid());var parameters=parameters(point);if(parameters.size()>50000)throw new IllegalArgumentException("More than 50,000 observed-polynomial targets.");var inference=Resampling.run(data,parameters,vector(point),resampling,(sample,rows)->vector(compute(sample,model,options,frozen,false)),progress,"Observed polynomial path equations","IID paired rows across all equations; centers, population SDs, every polynomial equation and all local derivatives are recomputed. Original-unit probe and grid values remain fixed. Fixed per-row composites commute with row resampling.");if(options.metric()!=PathProcess.Metric.UNSTANDARDIZED){Set<Integer> centered=new HashSet<>();for(var equation:point.polynomial().equations())if(equation.regressors().stream().allMatch(term->term.factors().length==1))centered.add(equation.target());inference=Resampling.suppressTests(inference,parameter->parameter.family().equals("Intercept")&&centered.contains(parameter.target()),"Tests suppressed for definitionally zero centered linear intercepts.");}List<String> warnings=new ArrayList<>(inference.warnings());warnings.addAll(point.warnings());inference=new Bootstrap.Result(inference.options(),inference.method(),inference.randomGenerator(),inference.signHandling(),inference.successful(),inference.failed(),inference.failures(),inference.estimates(),warnings,inference.estimator());return new Resampled(point,inference);}
}
